-- New account milestones observe authoritative native levels; no level cap changes.
INSERT INTO objectives_definitions(key,definition,revision)
SELECT rule->>'key',rule,1 FROM jsonb_array_elements($progression$[{"description":"Reach level 50 with any undeleted character on your account.","enabled":true,"key":"progression-v1.characters.level.50","kind":"achievement","objectives":[{"event":"account_character_level_progressed","filters":{"minimum_level":50},"key":"count","target":1}],"prerequisite_keys":[],"rewards":[{"kind":"scaled","policy_key":"content-v1.exploration"}],"schedule":{"timezone":"America/Bogota","type":"once"},"scope":"account","title":"Reach character level 50"},{"description":"Reach level 100 with any undeleted character on your account.","enabled":true,"key":"progression-v1.characters.level.100","kind":"achievement","objectives":[{"event":"account_character_level_progressed","filters":{"minimum_level":100},"key":"count","target":1}],"prerequisite_keys":[],"rewards":[{"kind":"scaled","policy_key":"content-v1.exploration"}],"schedule":{"timezone":"America/Bogota","type":"once"},"scope":"account","title":"Reach character level 100"},{"description":"Reach level 150 with any undeleted character on your account.","enabled":true,"key":"progression-v1.characters.level.150","kind":"achievement","objectives":[{"event":"account_character_level_progressed","filters":{"minimum_level":150},"key":"count","target":1}],"prerequisite_keys":[],"rewards":[{"kind":"scaled","policy_key":"content-v1.exploration"}],"schedule":{"timezone":"America/Bogota","type":"once"},"scope":"account","title":"Reach character level 150"},{"description":"Reach level 200 with any undeleted character on your account.","enabled":true,"key":"progression-v1.characters.level.200","kind":"achievement","objectives":[{"event":"account_character_level_progressed","filters":{"minimum_level":200},"key":"count","target":1}],"prerequisite_keys":[],"rewards":[{"kind":"scaled","policy_key":"content-v1.exploration"}],"schedule":{"timezone":"America/Bogota","type":"once"},"scope":"account","title":"Reach character level 200"},{"description":"Reach level 245 with any undeleted character on your account. This milestone becomes attainable when the server supports level 245; the current cap is 200.","enabled":true,"key":"progression-v1.characters.level.245","kind":"achievement","objectives":[{"event":"account_character_level_progressed","filters":{"minimum_level":245},"key":"count","target":1}],"prerequisite_keys":[],"rewards":[{"kind":"scaled","policy_key":"content-v1.exploration"}],"schedule":{"timezone":"America/Bogota","type":"once"},"scope":"account","title":"Reach character level 245"},{"description":"Have 2 distinct undeleted characters at level 200 or higher on your account.","enabled":true,"key":"progression-v1.characters.level.200.count.2","kind":"achievement","objectives":[{"event":"account_character_level_progressed","filters":{"minimum_level":200},"key":"count","target":2}],"prerequisite_keys":[],"rewards":[{"kind":"scaled","policy_key":"content-v1.exploration"}],"schedule":{"timezone":"America/Bogota","type":"once"},"scope":"account","title":"2 characters at level 200"},{"description":"Have 3 distinct undeleted characters at level 200 or higher on your account.","enabled":true,"key":"progression-v1.characters.level.200.count.3","kind":"achievement","objectives":[{"event":"account_character_level_progressed","filters":{"minimum_level":200},"key":"count","target":3}],"prerequisite_keys":[],"rewards":[{"kind":"scaled","policy_key":"content-v1.exploration"}],"schedule":{"timezone":"America/Bogota","type":"once"},"scope":"account","title":"3 characters at level 200"},{"description":"Reach level 100 in 1 distinct account profession. The same profession is counted once across heroes.","enabled":true,"key":"progression-v1.professions.level.100.count.1","kind":"achievement","objectives":[{"event":"account_profession_level_progressed","filters":{"minimum_level":100},"key":"count","target":1}],"prerequisite_keys":[],"rewards":[{"kind":"scaled","policy_key":"content-v1.exploration"}],"schedule":{"timezone":"America/Bogota","type":"once"},"scope":"account","title":"1 profession at level 100"},{"description":"Reach level 100 in 2 distinct account professions. The same profession is counted once across heroes.","enabled":true,"key":"progression-v1.professions.level.100.count.2","kind":"achievement","objectives":[{"event":"account_profession_level_progressed","filters":{"minimum_level":100},"key":"count","target":2}],"prerequisite_keys":[],"rewards":[{"kind":"scaled","policy_key":"content-v1.exploration"}],"schedule":{"timezone":"America/Bogota","type":"once"},"scope":"account","title":"2 professions at level 100"},{"description":"Reach level 100 in 3 distinct account professions. The same profession is counted once across heroes.","enabled":true,"key":"progression-v1.professions.level.100.count.3","kind":"achievement","objectives":[{"event":"account_profession_level_progressed","filters":{"minimum_level":100},"key":"count","target":3}],"prerequisite_keys":[],"rewards":[{"kind":"scaled","policy_key":"content-v1.exploration"}],"schedule":{"timezone":"America/Bogota","type":"once"},"scope":"account","title":"3 professions at level 100"}]$progression$::jsonb) rule
ON CONFLICT(key) DO NOTHING;
SELECT pg_notify('wakemu_objectives_updates','0');
